def slugify(text):
    text = text.lower()
    text = re.sub(r'[^\w\s-]', '', text)
    return '-'.join(w for w in text.split() if w).strip('-')[:80]

def get_img(idx):
    return fc_images[idx % len(fc_images)] if fc_images else ''

