created = 0
skipped = 0

for i, f in enumerate(formations):
    cursor.execute("SELECT id FROM Formation WHERE slug = ?", (f['slug'],))
    if cursor.fetchone():
        skipped += 1
        continue
    
    cover = get_img(i)
    
    try:
        cursor.execute("""
            INSERT INTO Formation (id, title, slug, shortDescription, fullDescription, level, duration,
                prerequisites, objectives, program, price, mode, coverImage, featured, "order", createdAt, updatedAt)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, (
            f"fc_{f['slug'][:35]}_{i}", f['title'], f['slug'], f['shortDescription'], f['fullDescription'],
            f['level'], f['duration'], f['prerequisites'], f['objectives'], f['program'],
            f['price'], f['mode'], cover, f['featured'], f['order'], now, now
        ))
        created += 1
        print(f"OK [{f['level']}] {f['title']}")
    except Exception as e:
        if 'UNIQUE' in str(e):
            skipped += 1
        else:
            print(f"ERR: {f['title']} - {e}")

conn.commit()

print(f"\n{'='*60}")
print(f"Creees: {created}, Ignored: {skipped}")

cursor.execute("""SELECT level, COUNT(*) FROM Formation GROUP BY level ORDER BY 
    CASE level WHEN 'Animateur' THEN 1 WHEN 'Superviseur' THEN 2 WHEN 'Responsable' THEN 3 WHEN 'Manager' THEN 4 END""")
print("\nPar niveau:")
for row in cursor.fetchall():
    print(f"  {row[0]}: {row[1]} formations")

cursor.execute("SELECT COUNT(*) FROM Formation")
print(f"\n  TOTAL: {cursor.fetchone()[0]} formations")

conn.close()